#![forbid(unsafe_code)]

use std::path::Path;

use rusqlite::Connection;

/// Every table this crate owns.
pub const TABLES: [&str; 1] = ["snap"];

pub const SCHEMA: &str = "CREATE TABLE IF NOT EXISTS snap (\n  id INTEGER PRIMARY KEY,\n  label TEXT NOT NULL,\n  captured_at_utc TEXT NOT NULL,\n  payload BLOB NOT NULL\n);\n";

/// Open (or create) `path` in WAL mode and apply [`SCHEMA`].
pub fn open(path: &Path) -> rusqlite::Result<Connection> {
    init(Connection::open(path)?)
}

pub fn open_in_memory() -> rusqlite::Result<Connection> {
    init(Connection::open_in_memory()?)
}

fn init(conn: Connection) -> rusqlite::Result<Connection> {
    let _mode: String = conn.query_row("PRAGMA journal_mode = WAL", [], |r| r.get(0))?;
    conn.execute_batch("PRAGMA synchronous = NORMAL;")?;
    conn.execute_batch(SCHEMA)?;
    Ok(conn)
}
